function MessageBubble({
  row,
  pending = false,
  showTimestamp = true,
}: {
  row: Pick<MessageRow, 'msgId' | 'text' | 'role' | 'createdAt'>;
  /** The optimistic "sending" echo — not yet confirmed by the server. */
  pending?: boolean;
  /** The welcome turn (§4.12) carries no real `createdAt` (it is minted
   * client-side from the join response, not a transcript row with a wire
   * timestamp) — `false` there, so the caption doesn't show a misleading
   * clock time for "epoch 0". */
  showTimestamp?: boolean;
}) {
  const { t } = useTranslation();
  const { locale } = useLocale();
  const isOwn = row.role !== 'assistant';

  return (
    <li
      data-testid="message-row"
      data-pending={pending || undefined}
      className={`flex ${isOwn ? 'justify-end' : 'justify-start'}`}
    >
      <div
        className={`max-w-[85%] rounded-2xl px-3 py-2 text-sm shadow-sm ${
          isOwn
            ? 'rounded-br-sm bg-slate-900 text-white dark:bg-slate-100 dark:text-slate-900'
            : 'rounded-bl-sm bg-white text-slate-800 ring-1 ring-slate-200 dark:bg-slate-800 dark:text-slate-100 dark:ring-slate-700'
        } ${pending ? 'opacity-60' : ''}`}
      >
        <p className="whitespace-pre-wrap break-words">{row.text}</p>
        {(pending || showTimestamp) && (
          <p
            className={`mt-1 text-[11px] ${
              isOwn ? 'text-slate-300 dark:text-slate-600' : 'text-slate-400 dark:text-slate-500'
            }`}
          >
            {pending ? t('chat.message.sending') : formatDate(row.createdAt, locale, { timeStyle: 'short' })}
          </p>
        )}
      </div>
    </li>
  );
}

function TurnIndicator({ turn }: { turn: TurnBlock | undefined }) {
  const { t } = useTranslation();
  if (!turn || turn.state === 'idle') return null;

  if (turn.state === 'thinking') {
    return (
      <p
        role="status"
        className="flex items-center gap-2 px-1 text-xs text-slate-500 dark:text-slate-400"
      >
        <span className="flex gap-0.5" aria-hidden="true">
          <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-slate-400 [animation-delay:-0.3s] motion-reduce:animate-none dark:bg-slate-500" />
          <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-slate-400 [animation-delay:-0.15s] motion-reduce:animate-none dark:bg-slate-500" />
          <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-slate-400 motion-reduce:animate-none dark:bg-slate-500" />
        </span>
        {t('chat.turn.thinking')}
      </p>
    );
  }

  // turn.state === 'queued'
  const text =
    turn.queuePosition === 0
      ? t('chat.turn.firstInLine')
      : t('chat.turn.aheadOfYou', { count: turn.queuePosition });

  return (
    <p role="status" className="px-1 text-xs text-slate-500 dark:text-slate-400">
      {text}
    </p>
  );
}

async function apiFetch<T>(opts: ApiFetchOptions): Promise<T> {
  const url = buildUrl(opts.path, opts.query);
  const headers: Record<string, string> = {};
  if (opts.body !== undefined) headers['Content-Type'] = 'application/json';
  if (opts.authHeader) headers.Authorization = opts.authHeader;

  const timeoutMs = opts.timeoutMs ?? DEFAULT_REQUEST_TIMEOUT_MS;
  const { signal, isTimeout, cleanup } = timedSignal(opts.signal, timeoutMs);

  let response: Response;
  try {
    response = await fetch(url, {
      method: opts.method,
      headers,
      body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
      signal,
    });
  } catch (err) {
    cleanup();
    if (isTimeout()) {
      // §5.3 C4's third shape: "a fetch that times out in the browser takes
      // the same branch" as a named/bodyless `504`.
      throw new ApiError({
        status: 504,
        body: null,
        method: opts.method,
        path: opts.path,
        credential: opts.credential,
        isTimeout: true,
      });
    }
    // An external cancellation (e.g. React Query unmount/refetch supersede) —
    // not a response, not a rule this dispatches on. Let it propagate as-is.
    throw err;
  }
  cleanup();

  if (response.ok) {
    if (response.status === 204) return undefined as T;
    const text = await response.text();
    return (text ? JSON.parse(text) : undefined) as T;
  }

  let body: ApiErrorBody = null;
  try {
    body = (await response.json()) as ApiErrorBody;
  } catch {
    // A bodyless/HTML proxy error (§5.3 C4's second shape) — `body` stays
    // `null`, and the status code alone must still carry the branch.
    body = null;
  }

  throw new ApiError({
    status: response.status,
    body,
    method: opts.method,
    path: opts.path,
    credential: opts.credential,
  });
}
